style.css:
@-moz-document domain("google.com") {
/* =========================
   BACKGROUND
========================= */

html,
body {
    background: url("https://i.imgur.com/BLroNY8.jpeg") center center/cover no-repeat fixed !important;
}

/* Hide Google's default background */
.L3eUgb {
    background: transparent !important;
}

/* =========================
   CUSTOM GOOGLE LOGO
========================= */

.lnXdpd {
    opacity: 0 !important;
    height: 140px !important;
}

.lnXdpd::after {
    content: "";
    display: block;
    width: 360px;
    height: 140px;
    margin: auto;
    background: url("https://i.imgur.com/5fy4DQF.png") center/contain no-repeat;
    opacity: 1 !important;
}

/* =========================
   SEARCH BAR
========================= */

.RNNXgb {
    background: #FFF9D9 !important;
    border: 4px solid #B8DBF8 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

.RNNXgb:hover,
.RNNXgb:focus-within {
    border-color: #8EC9F7 !important;
    box-shadow: none !important;
}

.gLFyf {
    color: #6C91B6 !important;
    font-size: 16px !important;
}

.gLFyf::placeholder {
    color: #9CB9D7 !important;
}

/* Search icons */

.z1asCe svg,
.goxjub,
.MhLuJb,
.Qwbd3 {
    fill: #7DB8EA !important;
}

/* =========================
   BUTTONS
========================= */

.gNO89b,
.RNmpXc {
    background: #FFF3B7 !important;
    border: 2px solid #B8DBF8 !important;
    color: #6C91B6 !important;
    border-radius: 20px !important;
    box-shadow: none !important;
}

.gNO89b:hover,
.RNmpXc:hover {
    background: #FFE98F !important;
    border-color: #8EC9F7 !important;
}

/* =========================
   HEADER
========================= */

#gb {
    background: transparent !important;
}

#gb a {
    color: #6C91B6 !important;
}

/* =========================
   FOOTER
========================= */

.uU7dJb {
    background: rgba(255,252,230,.90) !important;
}

.uU7dJb a {
    color: #6C91B6 !important;
}

/* =========================
   LINKS
========================= */

a {
    color: #6C91B6 !important;
}

/* Remove shadows */

* {
    text-shadow: none !important;
}
}
